ModuleDescriptor planningModule(){ModuleDescriptor m{"planning","Project Planning","planning/input",{}, {}};m.screens.append({"planning/input","PROJECT PLANNING — PERT/CPM",input,[](ApplicationShell& s,QMenuBar& b){menus(s,b,true);}});m.screens.append({"planning/result","PROJECT PLANNING — PERT/CPM",output,[](ApplicationShell& s,QMenuBar& b){menus(s,b,false);}});m.beforeLeave=[](ApplicationShell& shell,const QString&,const QString& to){return to.startsWith("planning/")?planningController(shell).commitInput():planningController(shell).leaveInput();};return m;}
bool printPlanning(QPrinter& printer,const PlanningController& c){if(!c.result())return false;QPainter p;if(!p.begin(&printer))return false;const auto area=printer.pageLayout().paintRectPixels(printer.resolution());auto font=p.font();font.setPointSize(10);p.setFont(font);qreal y=area.top();for(const auto& paragraph:c.outputText().split('\n')){QTextLayout layout(paragraph.isEmpty()?" ":paragraph,font,&printer);QTextOption option;option.setWrapMode(QTextOption::WrapAnywhere);layout.setTextOption(option);layout.beginLayout();while(true){auto line=layout.createLine();if(!line.isValid())break;line.setLineWidth(area.width());if(y+line.height()>area.bottom()){if(!printer.newPage()){p.end();return false;}y=area.top();}line.draw(&p,QPointF(area.left(),y));y+=line.height();}layout.endLayout();}const auto success=p.end();return success&&printer.printerState()!=QPrinter::Error;}
bool printPlanningSchedule(QPrinter& printer,const PlanningController& c){
 if(!c.result()||!c.schedule())return false;
 QPainter painter;if(!painter.begin(&printer))return false;
 const auto area=printer.pageLayout().paintRectPixels(printer.resolution());
 for(std::size_t first=0;first<c.problem().activities.size();first+=20){
  if(first&&!printer.newPage()){painter.end();return false;}
  QGraphicsScene scene;auto font=scene.font();font.setPointSize(10);scene.setFont(font);scheduleScene(scene,c,first,20);
  scene.render(&painter,QRectF(area),scene.sceneRect(),Qt::KeepAspectRatio);
 }
 return painter.end()&&printer.printerState()!=QPrinter::Error;
}

